      prompt: 'Write matmul(A, B) returning the product of an m×n and an n×p matrix as an m×p array of rows.',
      starter: 'function matmul(A, B) {\n  // result[i][j] = sum over k of A[i][k] * B[k][j]\n  return [];\n}\n',
      solution: 'function matmul(A, B) {\n  const rows = A.length;\n  const cols = B[0].length;\n  const inner = B.length;\n  const out = [];\n  for (let i = 0; i < rows; i += 1) {\n    const row = [];\n    for (let j = 0; j < cols; j += 1) {\n      let total = 0;\n      for (let k = 0; k < inner; k += 1) total += A[i][k] * B[k][j];\n      row.push(total);\n    }\n    out.push(row);\n  }\n  return out;\n}\n',
      tests: [
        { id: 'identity', label: 'Multiplying by the identity changes nothing', run: 'JSON.stringify(matmul([[1, 2]], [[1, 0], [0, 1]])) === JSON.stringify([[1, 2]])', hint: 'One row, two columns out.' },
        { id: 'square', label: 'A 2×2 product is correct', run: 'JSON.stringify(matmul([[1, 2], [3, 4]], [[5], [6]])) === JSON.stringify([[17], [39]])', hint: '1*5 + 2*6 = 17.' },
        { id: 'shape', label: 'Output rows equal input rows', run: 'matmul([[1, 0], [0, 1], [1, 1]], [[2, 2], [3, 3]]).length === 3', hint: 'Outer loop runs over A’s rows.' },
      ],
